def divide(dividendo, divisor):
    # Trate a divisão por zero com try/except
    pass

exercises.solution:
def divide(dividendo, divisor):
    try:
        return dividendo / divisor
    except ZeroDivisionError:
        print("Aviso: Não é possível dividir por zero!")
        return None

print(divide(10, 2))  # 5.0
print(divide(10, 0))  # None (com mensagem de aviso)

