def obter_preco(catalogo, produto):
    # Capture KeyError e retorne valor padrão
    pass

exercises.solution:
def obter_preco(catalogo, produto):
    try:
        return catalogo[produto]
    except KeyError:
        print(f"Produto '{produto}' não cadastrado no catálogo.")
        return 0.0

tabela = {"arroz": 25.50, "feijao": 8.90, "azeite": 38.00}
print(obter_preco(tabela, "arroz"))    # 25.50
print(obter_preco(tabela, "macarrao")) # 0.0

exercises.placeholder:
def valida_nota(nota):
    # Valide o intervalo da nota disparando ValueError
    pass

exercises.solution:
def valida_nota(nota):
    if nota < 0.0 or nota > 10.0:
        raise ValueError(f"Nota {nota} inválida! Deve estar entre 0.0 e 10.0.")
    return nota

try:
    valida_nota(8.5)   # Válido
    valida_nota(11.0)  # Lançará exceção
except ValueError as erro:
    print(f"Validação falhou: {erro}")
